 @Override void detail(String id,String type){
  JSONObject seed=openingMeta;openingMeta=null;clear("");detailPage=true;detailId=id;detailType=type;detailError="正在更新影片资料…";
  try{JSONObject cached=new JSONObject(prefs.getString("cinema.meta."+type+"."+id,""));if(DetailMetadata.useful(cached))seed=DetailMetadata.merge(seed,cached);}catch(Exception ignored){}
  if(seed==null)seed=new JSONObject();try{seed.put("id",id);seed.put("type",type);if(seed.optString("name").isEmpty())seed.put("name","影片资料加载中");}catch(Exception ignored){}
  final JSONObject initial=seed;renderDetail(initial,id,type);final int ticket=epoch;final JSONArray sources=addons;
  job(()->{try{JSONObject loaded=DetailMetadata.fetch(sources,id,type);JSONObject merged=DetailMetadata.merge(initial,loaded);runOnUiThread(()->{if(ticket!=epoch||!detailPage||!id.equals(detailId)||isFinishing())return;detailError="";renderDetail(merged,id,type);});}
   catch(Exception e){final String reason=LinkProbe.reason(e);runOnUiThread(()->{if(ticket!=epoch||!detailPage||!id.equals(detailId)||isFinishing())return;detailError="影片资料暂时无法更新 · "+reason;renderDetail(initial,id,type);});}});
 }
 @Override void renderDetail(JSONObject meta,String id,String type){
  int restoreY=detailPage&&id.equals(detailId)?scroll.getScrollY():0;homeCanvas=false;detailPage=true;detailId=id;detailType=type;carousel.removeCallbacks(tick);
  if(DetailMetadata.useful(meta))prefs.edit().putString("cinema.meta."+type+"."+id,meta.toString()).apply();
  if(!type.equals("movie"))super.renderDetail(meta,id,type);detailChrome=new DetailChrome(this,meta,id,type);detailChrome.apply();updateInsets();if(restoreY>0)scroll.post(()->scroll.scrollTo(0,restoreY));
 }
