 void selectSource(String queryId,String type,JSONObject meta,boolean start,java.util.function.Consumer<JSONObject> selected){
  final int ticket=epoch;final String parent=detailId;final boolean ownerDetail=detailPage;
  if(ownerDetail&&!queryId.equals(parent)&&!EpisodeActions.belongs(meta,parent,queryId)){say("请先选择本剧的具体集数");return;}
  if(ownerDetail&&type.equals("series")&&queryId.equals(parent)){if(detailChrome!=null)detailChrome.chooseEpisode(()->detailChrome.selectForAction(start,selected));return;}
  new StremioSourceDialog(this,addons,queryId,type,meta,(stream,all)->{if(isFinishing()||ticket!=epoch||ownerDetail&&(!detailPage||!parent.equals(detailId)))return;picked.put(queryId,stream);pickedAll.put(queryId,all);if(ownerDetail&&EpisodeActions.belongs(meta,parent,queryId))detailEpisodes.put(EpisodeActions.key(type,parent),queryId);if(detailChrome!=null&&ownerDetail)detailChrome.refresh();if(selected!=null)selected.accept(stream);if(start){currentSources=all;sourceEpisode=queryId;play(stream,queryId,type,meta);}},()->addDialog(""));
 }
